/* ============ Inicio / ruta del aprendiz ============ */
const ROUTE_STEPS = [
  ['Creación de productos', 'El aprendiz escribe el título y la descripción del artículo.', () => S.products.length >= 1, '#/productos/nuevo', 'Crear producto'],
  ['Configuración comercial', 'El aprendiz define el precio y carga imágenes cumpliendo los estándares de calidad.', () => S.products.some(p => p.price > 0 && p.images.length >= 1 && productQuality(p).score >= 70), '#/productos', 'Completar productos'],
  ['Selección de pauta', 'El aprendiz elige los artículos creados para promocionarlos.', () => S.campaigns.some(c => c.ads.length) || (S.draft && S.draft.ads.length > 0), '#/campanas/nueva', 'Elegir artículos'],
  ['Segmentación de audiencia', 'El aprendiz define el público por comportamiento e intereses.', () => S.campaigns.some(c => c.audience.touched) || (S.draft && S.draft.audience.touched), '#/campanas/nueva', 'Definir audiencia'],
  ['Asignación de palabras clave', 'El aprendiz ingresa términos de búsqueda con coincidencia amplia o exacta.', () => S.campaigns.some(c => c.ads.some(a => a.keywords.length)) || (S.draft && S.draft.ads.some(a => a.keywords.length)), '#/campanas/nueva', 'Asignar palabras'],
  ['Definición de presupuesto', 'El aprendiz asigna el dinero de la campaña publicitaria y la lanza.', () => S.campaigns.some(c => c.status !== 'draft'), '#/campanas/nueva', 'Asignar presupuesto'],
  ['Análisis de resultados', 'El sistema muestra métricas de campaña pagada. El aprendiz calcula el ACOS y elabora un reporte de rendimiento.', () => S.reports.length >= 1, '#/metricas', 'Analizar resultados']
];
VIEWS.inicio = () => {
  const done = ROUTE_STEPS.map(s => !!s[2]()); const n = done.filter(Boolean).length; const next = done.indexOf(false);
  return `<div class="page">
  <section class="hero"><div class="col gap8"><span class="badge" style="background:rgba(255,255,255,.2);color:#fff;align-self:flex-start">Simulador de publicidad en marketplace</span><h1 class="t-h2" style="color:#fff">Hola, ${esc(S.seller.name)}</h1><p style="opacity:.92">Crea productos, lanza campañas con bloques y anuncios, mide resultados y calcula el ACOS como lo haces en un marketplace real. Todo se guarda en este navegador.</p><div class="bar mt8"><i style="width:${n / 7 * 100}%"></i></div><div class="row between t-sm"><span>${n} de 7 etapas completadas</span><span>Día simulado ${S.sim.day}</span></div></div></section>
  ${n === 0 && !S.products.length ? `<section class="card row gap12 wrap"><div class="grow"><h3 class="t-h3">¿Quieres ver el simulador en acción?</h3><p class="c-var">Carga un caso práctico con 6 productos, 3 campañas y 30 días de resultados simulados.</p></div><button class="btn pri" data-act="practice">${ic('zap', 's18')} Cargar caso práctico</button></section>` : ''}
  <div class="col gap12">${ROUTE_STEPS.map((s, i) => `<article class="card route-step ${i === next ? 'hl' : ''}"><div class="num ${done[i] ? 'done' : 'todo'}">${done[i] ? ic('check', 's18') : i + 1}</div><div class="grow col gap4"><h3 class="t-h3">${s[0]}</h3><p class="c-var">${s[1]}</p><div class="row gap8 wrap mt4"><a class="btn ${i === next ? 'pri' : 'gho'} sm" href="${i === 2 && S.draft ? '#/campanas/nueva' : s[3]}">${s[4]} ${ic('arr', 's14')}</a>${i === 6 ? `<a class="btn gho sm" href="#/acos">${ic('calc', 's14')} Calculadora ACOS</a><a class="btn gho sm" href="#/reporte">${ic('file', 's14')} Reporte</a>` : ''}</div></div>${done[i] ? '<span class="badge ok">Listo</span>' : ''}</article>`).join('')}</div>
  <section class="card col gap12"><h3 class="t-h3">Fórmulas clave</h3><div class="grid2">
    ${statBox('ACOS', 'Inversión ÷ Ventas × 100', 'Costo publicitario sobre las ventas que generó el anuncio')}${statBox('ROAS', 'Ventas ÷ Inversión', 'Es el inverso del ACOS: ROAS = 100 ÷ ACOS')}${statBox('CTR', 'Clics ÷ Impresiones', 'Qué tan atractivo es el anuncio')}${statBox('CPC', 'Inversión ÷ Clics', 'Lo que pagas en promedio por clic')}</div>
    <p class="hint">Un anuncio es rentable cuando su ACOS es menor al margen del producto (ACOS de equilibrio).</p></section></div>`;
};

/* ============ Anuncios ============ */
VIEWS.anuncios = () => {
  const all = []; S.campaigns.forEach(c => c.ads.forEach(a => all.push([c, a])));
  const key = { clicks: m => -m.clicks, imp: m => -m.imp, sales: m => -m.sales, acos: m => isFinite(m.acos) ? m.acos : 1e9 }[UI.adsSort];
  let list = all.filter(([c, a]) => (UI.adsCamp === 'all' || c.id === UI.adsCamp) && prodById(a.productId) && (norm(prodById(a.productId).title + ' ' + a.id).includes(norm(UI.adsQ)))).sort((x, y) => key(adMetrics(x[1])) - key(adMetrics(y[1])));
  const eff = a => UI.pending[a.id] ?? a.active; const act = list.filter(([, a]) => eff(a)).length; const pend = Object.keys(UI.pending).length;
  const rec = list.filter(([, a]) => adProfitable(a)).length;
  const sortChip = (k, l) => `<button class="chip ${UI.adsSort === k ? 'on' : ''}" data-act="sortAds" data-k="${k}">${l}${UI.adsSort === k ? ic(k === 'acos' ? 'up' : 'dn', 's14') : ''}</button>`;
  return `<div class="page">${pageHead('Anuncios de productos', '', 'Cada anuncio es un producto promocionado dentro de una campaña')}
  ${banner(3, 'Activa tus anuncios con mejor rendimiento', 'Prioriza los que tienen buen volumen de visitas y ventas y un ACOS por debajo del margen del producto.', `<div class="row gap4 c-pri t-lbl mt4">${ic('checkc', 's16')}<span>${rec} anuncio${rec === 1 ? '' : 's'} recomendado${rec === 1 ? '' : 's'} por rentabilidad</span></div>`)}
  <div class="search">${ic('search', 's18 ic')}<input id="adsq" type="search" placeholder="Buscar publicaciones o ID..." value="${esc(UI.adsQ)}" aria-label="Buscar anuncios"></div>
  <div class="row gap8 wrap"><select class="sel grow" id="adsc" aria-label="Filtrar por campaña" style="min-width:180px"><option value="all">Todas las campañas</option>${S.campaigns.map(c => `<option value="${c.id}" ${UI.adsCamp === c.id ? 'selected' : ''}>${esc(c.name)}</option>`).join('')}</select></div>
  <div class="chips">${sortChip('clicks', 'Clics')}${sortChip('imp', 'Impresiones')}${sortChip('sales', 'Ventas')}${sortChip('acos', 'ACOS')}</div>
  <div class="row between"><label class="row gap8 t-lbl" style="cursor:pointer"><input type="checkbox" id="adsrec" style="width:18px;height:18px;accent-color:#39a900" ${list.length && list.filter(([, a]) => adProfitable(a)).every(([, a]) => eff(a)) && rec ? 'checked' : ''}> Seleccionar recomendados</label><span class="t-xs c-sec">${list.length} publicaciones disponibles</span></div>
  ${list.length ? list.map(([c, a]) => adCard(c, a, 'pending')).join('') : emptyState('Aún no tienes anuncios', 'Los anuncios se crean al lanzar una campaña con productos.', `<button class="btn pri" data-act="newCamp">${ic('plusc', 's18')} Crear campaña</button>`)}
  ${list.length ? `<div class="sticky-bar"><div class="row gap8"><span class="dotg pu"></span><div class="col"><span class="t-lbl b">${act} de ${list.length} activos</span><span class="t-xs c-sec">En pauta publicitaria${pend ? ' · ' + pend + ' cambio' + (pend > 1 ? 's' : '') + ' sin aplicar' : ''}</span></div></div><button class="btn pri" data-act="applyAds" ${pend ? '' : 'disabled'}>Aplicar cambios ${ic('checkc', 's16')}</button></div>` : ''}</div>`;
};
VIEWS.anuncios_after = () => {
  const q = $('#adsq'); if (q) q.addEventListener('input', () => { UI.adsQ = q.value; const p = q.selectionStart; rerender(); const n = $('#adsq'); n.focus(); n.setSelectionRange(p, p); });
  const c = $('#adsc'); if (c) c.addEventListener('change', () => { UI.adsCamp = c.value; rerender(); });
  const r = $('#adsrec'); if (r) r.addEventListener('change', () => {
    S.campaigns.forEach(c => c.ads.forEach(a => { const p = prodById(a.productId); if (!p) return; const m = adMetrics(a); if (UI.adsCamp !== 'all' && c.id !== UI.adsCamp) return; if (adProfitable(a)) UI.pending[a.id] = true; else if (m.sales > 0 || m.clicks > 30) UI.pending[a.id] = false; }));
    Object.keys(UI.pending).forEach(id => { const f = findAd(id); if (f && f.ad.active === UI.pending[id]) delete UI.pending[id]; }); rerender();
  });
};
ACT.sortAds = el => { UI.adsSort = el.dataset.k; rerender(); };
ACT.applyAds = () => { let n = 0; Object.entries(UI.pending).forEach(([id, v]) => { const f = findAd(id); if (f && f.ad.active !== v) { f.ad.active = v; n++; } }); UI.pending = {}; save(); toast(n ? `Se aplicaron ${n} cambio${n > 1 ? 's' : ''}` : 'Sin cambios'); rerender(); };

/* ============ Detalle de un anuncio ============ */
function coach(a, p, c, m) {
  const t = [], be = margin(p);
  if (!m.imp) return ['Aún no hay datos. Simula días para recibir recomendaciones.'];
  if (m.sales === 0 && m.clicks > 40) t.push('Tiene clics pero ninguna venta. Revisa precio, descripción y fotos: el problema está después del clic.');
  if (isFinite(m.acos) && m.acos > be) t.push(`El ACOS (${pct(m.acos)}) supera el margen (${pct(be)}): cada venta te deja pérdida. Baja la puja, mejora la publicación o pausa el anuncio.`);
  else if (isFinite(m.acos) && m.acos <= be * .5) t.push(`Muy rentable: el ACOS (${pct(m.acos)}) es menos de la mitad del margen. Puedes subir presupuesto o puja para ganar más volumen.`);
  if (m.ctr < .8) t.push('El CTR es bajo (' + pct(m.ctr, 2) + '). Mejora el título y la foto principal, o usa coincidencia más precisa.');
  if (m.clicks > 40 && m.cvr < 1.5) t.push('La conversión es baja (' + pct(m.cvr, 2) + '). Revisa el precio frente a la competencia y completa la descripción.');
  if (productQuality(p).score < 70) t.push(`La calidad de la publicación es ${productQuality(p).score}/100. Mejorarla reduce el costo por venta.`);
  const k = a.keywords; if (!k.length) t.push('No tiene palabras clave propias. Agrega términos específicos para controlar a quién llegas.');
  if (!t.length) t.push('El anuncio rinde dentro de lo esperado. Sigue monitoreando el ACOS semanalmente.');
  return t;
}
VIEWS.anuncio = r => {
  const f = findAd(r.a); if (!f) return `<div class="page">${emptyState('Anuncio no encontrado', 'Pudo haber sido eliminado.', '<a class="btn pri" href="#/anuncios">Ver anuncios</a>')}</div>`;
  const { camp: c, ad: a } = f; const p = prodById(a.productId); if (!p) return `<div class="page">${emptyState('Producto eliminado', '', '<a class="btn pri" href="#/anuncios">Volver</a>')}</div>`;
  const m = adMetrics(a), be = margin(p), [bk, bt] = acosBadge(m.acos, p); const days = []; for (let d = S.sim.day - 1; d >= Math.max(c.startDay, S.sim.day - 10); d--) days.push([d, a.daily[d]]);
  const profit = adNet(a);
  return `<div class="page"><div class="row gap8"><a class="icon-btn" href="#/campanas/${c.id}/anuncios" aria-label="Volver">${ic('arl', 's24')}</a><h1 class="t-h2">Resultado del anuncio</h1></div>
  <section class="card col gap12"><div class="row-top gap12">${thumb(p)}<div class="grow col gap4"><h2 class="t-h3" style="line-height:22px">${esc(p.title)}</h2><div class="row gap8 wrap"><span class="badge info">${esc(c.name)}</span><span class="badge mut">${esc((groupOf(c, a) || {}).name || '')}</span><span class="badge ${bk}">${bt}</span></div><span class="t-m c-prc">${money(p.price)}</span></div>${sw(a.active, 'adSwitch', `data-ad="${a.id}"`)}</div></section>
  ${S.sim.day <= c.startDay ? `<div class="card hl"><h3 class="t-h3">Anuncio publicado</h3><p class="c-var">Aún no hay resultados. Avanza el tiempo para ver cómo responde el mercado.</p></div>` : ''}${simBar()}
  <div class="grid2">${statBox('Impresiones', int(m.imp), 'CTR ' + pct(m.ctr, 2))}${statBox('Clics', int(m.clicks), 'CPC ' + money(m.cpc))}${statBox('Inversión', money(m.cost))}${statBox('Ventas', int(m.sales) + ' u.', 'Conversión ' + pct(m.cvr, 2))}${statBox('Ingresos por ads', money(m.revenue))}${statBox('ACOS', pct(m.acos), 'ROAS ' + (isFinite(m.roas) ? m.roas.toFixed(1).replace('.', ',') + 'x' : '—'), acosCls(m.acos, p))}</div>
  <section class="card col gap8"><h3 class="t-h3">¿Es rentable?</h3><div class="row between"><span>Margen del producto (ACOS de equilibrio)</span><b>${pct(be)}</b></div><div class="row between"><span>ACOS del anuncio</span><b class="${acosCls(m.acos, p)}">${pct(m.acos)}</b></div><div class="row between"><span>Utilidad neta después de publicidad</span><b class="${profit >= 0 ? 'c-pri' : 'c-err'}">${money(profit)}</b></div><p class="hint">Utilidad neta = ventas × (precio − costo) − inversión publicitaria.</p></section>
  ${S.sim.day > c.startDay ? `<section class="card col gap8"><h3 class="t-h3">Inversión vs ingresos</h3>${lineChart([{ ads: [a] }], c.startDay, S.sim.day - 1)}</section>` : ''}
  <section class="card col gap8"><h3 class="t-h3">Recomendaciones del sistema</h3>${coach(a, p, c, m).map(x => `<div class="check"><span class="ic ok">${ic('bulb', 's14')}</span><span>${esc(x)}</span></div>`).join('')}</section>
  <section class="card col gap8"><div class="row between"><h3 class="t-h3">Palabras clave</h3><a class="btn gho sm" href="#/campanas/${c.id}/palabras">${ic('edit', 's14')} Editar</a></div>${(a.keywords.length ? a.keywords : autoKeywords(p, c.bid)).map(k => `<div class="row between t-md"><span class="b">${esc(k.term)}</span><span class="c-sec">${MATCH[k.match].n} · ${money(k.bid)}</span></div>`).join('')}</section>
  ${days.length ? `<section class="card col gap8"><h3 class="t-h3">Últimos días</h3><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Día</th><th class="num">Impr.</th><th class="num">Clics</th><th class="num">Inversión</th><th class="num">Ventas</th><th class="num">ACOS</th></tr></thead><tbody>${days.map(([d, x]) => x ? `<tr><td>Día ${d + 1}</td><td class="num">${int(x.imp)}</td><td class="num">${int(x.clicks)}</td><td class="num">${money(x.cost)}</td><td class="num">${x.sales}</td><td class="num">${pct(x.revenue ? x.cost / x.revenue * 100 : NaN)}</td></tr>` : '').join('')}</tbody></table></div></section>` : ''}</div>`;
};

/* ============ Métricas ============ */
function bestCamp(camps = S.campaigns) { const el = camps.map(c => [c, campMetrics(c)]).filter(([, m]) => m.sales >= 5 && isFinite(m.acos)); el.sort((a, b) => a[1].acos - b[1].acos); return el[0] || null; }
VIEWS.metricas = () => {
  const from = rangeFrom(), to = S.sim.day - 1; const has = S.campaigns.some(c => c.status !== 'draft') && to >= 0;
  const m = allMetrics(from, to), org = organicSum(from, to); const tot = m.revenue + org.revenue; const share = tot ? m.revenue / tot * 100 : 0; const best = bestCamp();
  const rc = (k, l) => `<button class="chip ${UI.range === k ? 'on' : ''}" data-act="range" data-k="${k}">${l}</button>`;
  const camps = S.campaigns.filter(c => c.status !== 'draft').map(c => ({ c, m: campMetrics(c, from, to) })).sort((a, b) => (isFinite(a.m.acos) ? a.m.acos : 1e9) - (isFinite(b.m.acos) ? b.m.acos : 1e9));
  if (!S.campaigns.some(c => c.status !== 'draft')) return `<div class="page">${pageHead('Rendimiento')}${emptyState('Aún no hay campañas lanzadas', 'Lanza una campaña y simula días para ver aquí sus métricas de campaña pagada.', `<div class="row gap8 wrap" style="justify-content:center"><button class="btn pri" data-act="newCamp">${ic('plusc', 's18')} Crear campaña</button><button class="btn sec" data-act="practice">${ic('zap', 's18')} Cargar caso práctico</button></div>`)}</div>`;
  return `<div class="page wide">${pageHead(`Rendimiento <span class="dotg pu" style="display:inline-block"></span>`, '', rangeLabel() + (to >= 0 ? ` · días ${from + 1} a ${to + 1}` : ''))}
  <div class="chips">${rc(1, 'Último día')}${rc(7, '7 días')}${rc(30, '30 días')}${rc('all', 'Todo')}</div>${simBar()}
  ${has ? `<section class="hero"><div class="row-top between gap12"><div class="col gap4"><div class="row gap8"><span class="badge" style="background:rgba(255,255,255,.2);color:#fff">Atribución directa</span><span class="t-xs row gap4" style="opacity:.9">${ic('zap', 's14')} ${share >= 30 ? 'Alta eficiencia' : 'Por mejorar'}</span></div><p class="t-h3" style="color:#fff;font-weight:800">${pct(share, 0)} de tus ventas</p><p class="t-sm" style="opacity:.9">fueron generadas directamente gracias a tus publicaciones patrocinadas en MercadoSENA Ads.</p></div>${ic('chart', 's32')}</div><div class="mt12 col gap8"><div class="bar"><i style="width:${share}%"></i></div><div class="row between t-xs"><span>● Product Ads: ${moneyC(m.revenue)}</span><span style="opacity:.8">Orgánico: ${moneyC(org.revenue)}</span></div></div></section>` : '<div class="card hl"><p class="c-var">Aún no transcurre ningún día. Avanza el tiempo para ver resultados.</p></div>'}
  <div class="col gap8"><div class="row between"><span class="t-lblm b">Resumen de métricas clave</span><span class="t-xs c-sec">Desliza para ver más</span></div><div class="swipe">
    <div class="kpi"><div class="row between"><span class="t-xs c-sec up">Ventas Ads</span></div><span class="t-m xb">${money(m.revenue)}</span><span class="t-xs c-sec">${int(m.sales)} unidades</span></div>
    <div class="kpi"><div class="row between"><span class="t-xs c-sec up">Retorno (ROAS)</span>${ic('star', 's16')}</div><span class="t-m xb c-prc">${isFinite(m.roas) ? m.roas.toFixed(1).replace('.', ',') + 'x' : '—'}</span><span class="t-xs c-sec">${isFinite(m.roas) ? `Ganas $ ${m.roas.toFixed(1).replace('.', ',')} por cada $ 1 invertido` : 'Sin ventas aún'}</span></div>
    <div class="kpi"><div class="row between"><span class="t-xs c-sec up">Inversión total</span>${ic('dollar', 's16')}</div><span class="t-m xb">${money(m.cost)}</span><span class="t-xs c-sec">ACOS ${pct(m.acos)}</span></div>
    <div class="kpi"><div class="row between"><span class="t-xs c-sec up">Clics &amp; CPC</span>${ic('click', 's16')}</div><span class="t-m xb">${int(m.clicks)}</span><span class="t-xs c-sec">CPC promedio: ${money(m.cpc)}</span></div>
    <div class="kpi"><div class="row between"><span class="t-xs c-sec up">Impresiones</span>${ic('eye', 's16')}</div><span class="t-m xb">${compact(m.imp)}</span><span class="t-xs c-sec">CTR prom.: ${pct(m.ctr, 2)}</span></div></div></div>
  <div class="grid-auto" style="grid-template-columns:repeat(auto-fit,minmax(300px,1fr))"><section class="card col gap8"><div><h3 class="t-lblm b">Ventas por publicidad vs orgánico</h3><p class="t-sm c-sec">Ingresos por día o semana en el periodo</p></div><div class="legend t-xs"><span><i style="background:var(--primary-container)"></i>Con publicidad</span><span><i style="background:var(--surface-highest)"></i>Sin publicidad (orgánico)</span></div>${barsChart(from, to, S.campaigns)}</section>
  <section class="card col gap8"><div><h3 class="t-lblm b">Inversión vs ingresos por ads</h3><p class="t-sm c-sec">Todas las campañas</p></div>${lineChart(S.campaigns, from, to)}</section></div>
  ${best ? `<section class="card col gap8"><div class="row between"><h3 class="t-lblm b">Campaña más rentable</h3><span class="badge ok">${ic('award', 's14')} Mejor ACOS</span></div><div class="row gap12 card flat">${thumb(prodById((best[0].ads[0] || {}).productId), 'sm')}<div class="grow"><div class="b">${esc(best[0].name)}</div><div class="t-sm c-sec">${int(best[1].sales)} ventas · ${best[0].ads.length} anuncios</div><div class="row gap8 mt4"><span class="t-xs c-pri xb">ROAS ${best[1].roas.toFixed(1).replace('.', ',')}x</span><span class="t-xs c-sec">• ACOS ${pct(best[1].acos)}</span></div></div><a class="icon-btn" href="#/campanas/${best[0].id}/resultados" aria-label="Ver campaña">${ic('sliders', 's18')}</a></div></section>` : ''}
  <section class="card col gap8"><h3 class="t-lblm b">Campañas en el periodo</h3><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Campaña</th><th class="num">Inversión</th><th class="num">Ventas</th><th class="num">Ingresos</th><th class="num">ACOS</th><th class="num">ROAS</th><th class="num">Utilidad neta</th></tr></thead><tbody>${camps.map((x, i) => { const np = netProfit(x.c, from, to); return `<tr class="${best && best[0] === x.c ? 'best' : ''}"><td><a class="b" href="#/campanas/${x.c.id}/resultados">${esc(x.c.name)}</a></td><td class="num">${money(x.m.cost)}</td><td class="num">${int(x.m.sales)}</td><td class="num">${money(x.m.revenue)}</td><td class="num b ${acosCls(x.m.acos)}">${pct(x.m.acos)}</td><td class="num">${isFinite(x.m.roas) ? x.m.roas.toFixed(1).replace('.', ',') + 'x' : '—'}</td><td class="num b ${np >= 0 ? 'c-pri' : 'c-err'}">${money(np)}</td></tr>`; }).join('')}</tbody></table></div></section>
  <div class="row gap8 wrap"><button class="btn pri grow" data-act="newCamp">${ic('plusc', 's18')} Crear nueva campaña</button><a class="btn sec grow" href="#/acos">${ic('calc', 's18')} Calcular ACOS</a><a class="btn sec grow" href="#/reporte">${ic('file', 's18')} Elaborar reporte</a></div>
  <div class="tip"><div class="ic">${ic('bulb', 's24')}</div><div class="col"><span class="t-lbl b">Consejo de optimización SENA</span><p class="t-sm c-var" style="margin-top:2px">Usa las métricas de clics y ROAS para redistribuir tu presupuesto hacia los productos con mayor conversión y pausa los anuncios cuyo ACOS supere su margen.</p></div></div></div>`;
};
ACT.range = el => { UI.range = el.dataset.k === 'all' ? 'all' : +el.dataset.k; rerender(); };

/* ============ Calculadora ACOS ============ */
const CALC = { spend: 0, sales: 0, margin: 0 };
function calcOut() {
  const a = CALC.sales > 0 ? CALC.spend / CALC.sales * 100 : NaN, ro = CALC.spend > 0 ? CALC.sales / CALC.spend : NaN;
  return `<div class="grid2">${statBox('ACOS', pct(a, 2), 'Inversión ÷ Ventas × 100', isFinite(a) ? (CALC.margin ? (a <= CALC.margin ? 'c-pri' : 'c-err') : '') : '')}${statBox('ROAS', isFinite(ro) ? ro.toFixed(2).replace('.', ',') + 'x' : '—', 'Ventas ÷ Inversión')}</div>${CALC.margin && isFinite(a) ? `<p class="${a <= CALC.margin ? 'ok-txt' : 'bad-txt'}">${a <= CALC.margin ? 'Rentable: el ACOS está por debajo de tu margen.' : 'Pierdes dinero: el ACOS supera tu margen.'}</p>` : ''}`;
}
function liveAcos() { const e = $('#calcout'); if (e) e.innerHTML = calcOut(); }
const acosRows = () => { const out = []; S.campaigns.filter(c => c.status !== 'draft').forEach(c => c.ads.forEach(a => { const p = prodById(a.productId); if (!p) return; const m = adMetrics(a); out.push({ c, a, p, m }); })); return out; };
const near = (v, t) => v !== '' && v != null && Math.abs(num(v) - t) <= .1;
VIEWS.acos = () => {
  const rows = acosRows(), K = S.acos, camps = S.campaigns.filter(c => c.status !== 'draft').map(c => ({ c, m: campMetrics(c) }));
  const best = bestCamp(); const withData = rows.filter(r => r.m.imp > 0);
  const ver = K.checked;
  return `<div class="page">${pageHead('Calculadora de ACOS')}
  ${banner(7, 'Análisis de resultados', 'Calcula manualmente el ACOS de cada anuncio y resuelve cuál es la campaña de mejor rendimiento.')}
  <section class="card col gap12"><h3 class="t-h3">1. Calculadora libre</h3><div class="grid2"><div class="field"><label for="ac-s">Inversión publicitaria (COP)</label><input id="ac-s" class="inp" type="number" inputmode="decimal" data-root="ac" data-set="spend" data-type="num" value="${CALC.spend || ''}"></div><div class="field"><label for="ac-v">Ventas por publicidad (COP)</label><input id="ac-v" class="inp" type="number" inputmode="decimal" data-root="ac" data-set="sales" data-type="num" value="${CALC.sales || ''}"></div></div><div class="field"><label for="ac-m">Margen del producto % (opcional)</label><input id="ac-m" class="inp" type="number" inputmode="decimal" data-root="ac" data-set="margin" data-type="num" value="${CALC.margin || ''}"></div><div id="calcout" class="col gap8">${calcOut()}</div></section>
  <section class="card flat col gap8"><div class="t-lblm b">Fórmulas</div><div class="t-md">ACOS = Inversión publicitaria ÷ Ventas generadas por la publicidad × 100</div><div class="t-md">ROAS = Ventas ÷ Inversión = 100 ÷ ACOS</div><div class="t-md">ACOS de equilibrio = margen bruto del producto %</div></section>
  <section class="card col gap12"><div><h3 class="t-h3">2. Ejercicio: ACOS de cada anuncio</h3><p class="c-sec t-sm">Usa los datos de tus anuncios (periodo completo). Escribe el ACOS en % con dos decimales y verifica.</p></div>
  ${withData.length ? `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Anuncio</th><th class="num">Inversión</th><th class="num">Ingresos ads</th><th class="num">Tu ACOS (%)</th>${ver ? '<th>Resultado</th>' : ''}</tr></thead><tbody>${withData.map(({ c, a, p, m }) => { const ans = K.answers[a.id]; const ok = near(ans, m.acos); return `<tr><td><div class="b">${esc(p.title.slice(0, 30))}${p.title.length > 30 ? '…' : ''}</div><div class="t-xs c-sec">${esc(c.name)}</div></td><td class="num">${money(m.cost)}</td><td class="num">${money(m.revenue)}</td><td class="num">${isFinite(m.acos) ? `<input class="inp" type="number" step="0.01" inputmode="decimal" aria-label="ACOS de ${esc(p.title)}" data-root="ax" data-set="answers.${a.id}" value="${ans ?? ''}">` : '<span class="c-sec">Sin ventas</span>'}</td>${ver ? `<td>${!isFinite(m.acos) ? '—' : ok ? `<span class="ok-txt">✓ Correcto</span>` : `<span class="bad-txt">✗ ${pct(m.acos, 2)}</span><div class="t-xs c-sec">${int(m.cost)} ÷ ${int(m.revenue)} × 100</div>`}</td>` : ''}</tr>`; }).join('')}</tbody></table></div>
  <div class="row gap8 wrap"><button class="btn pri" data-act="checkAcos">${ic('checkc', 's16')} Verificar respuestas</button>${ver ? `<span class="t-lbl b">${withData.filter(r => isFinite(r.m.acos) && near(K.answers[r.a.id], r.m.acos)).length} de ${withData.filter(r => isFinite(r.m.acos)).length} correctas</span>` : ''}</div>`
      : emptyState('Aún no hay datos', 'Lanza una campaña y simula días para tener inversión e ingresos con los cuales calcular el ACOS.', `<button class="btn pri" data-act="practice">${ic('zap', 's18')} Cargar caso práctico</button>`)}</section>
  ${camps.some(x => x.m.imp > 0) ? `<section class="card col gap12"><div><h3 class="t-h3">3. ¿Cuál es la campaña de mejor rendimiento?</h3><p class="c-sec t-sm">Calcula el ACOS de cada campaña, compáralas y elige la mejor. Criterio: menor ACOS con al menos 5 ventas.</p></div>
  <div class="tbl-wrap"><table class="tbl"><thead><tr><th>Campaña</th><th class="num">Inversión</th><th class="num">Ingresos ads</th><th class="num">Ventas</th><th class="num">Tu ACOS (%)</th>${ver ? '<th>Resultado</th>' : ''}</tr></thead><tbody>${camps.map(({ c, m }) => { const ans = K.camp[c.id]; return `<tr><td class="b">${esc(c.name)}</td><td class="num">${money(m.cost)}</td><td class="num">${money(m.revenue)}</td><td class="num">${int(m.sales)}</td><td class="num">${isFinite(m.acos) ? `<input class="inp" type="number" step="0.01" aria-label="ACOS de ${esc(c.name)}" data-root="ax" data-set="camp.${c.id}" value="${ans ?? ''}">` : '—'}</td>${ver ? `<td>${!isFinite(m.acos) ? '—' : near(ans, m.acos) ? '<span class="ok-txt">✓ Correcto</span>' : `<span class="bad-txt">✗ ${pct(m.acos, 2)}</span>`}</td>` : ''}</tr>`; }).join('')}</tbody></table></div>
  <div class="field"><span class="lbl">Mi decisión: la campaña de mejor rendimiento es…</span><div class="col gap8">${camps.map(({ c }) => `<div class="opt ${K.best === c.id ? 'on' : ''}" data-act="pickBest" data-id="${c.id}" role="radio" aria-checked="${K.best === c.id}" tabindex="0"><div class="radio"><i></i></div><div class="b">${esc(c.name)}</div></div>`).join('')}</div></div>
  <div class="field"><label for="why">Justifica tu decisión</label><textarea id="why" class="txt" data-root="ax" data-set="why" placeholder="Explica con datos de ACOS, ROAS y utilidad neta…">${esc(K.why)}</textarea></div>
  <button class="btn pri" data-act="checkAcos">${ic('checkc', 's16')} Verificar mi decisión</button>
  ${ver && K.best ? `<div class="card ${best && best[0].id === K.best ? '' : ''}" style="background:${best && best[0].id === K.best ? 'rgba(138,253,93,.25)' : 'var(--amber-bg)'}"><h3 class="t-h3">${best && best[0].id === K.best ? '¡Correcto!' : 'Revisa tu análisis'}</h3><p>${best ? `La campaña de mejor rendimiento es <b>${esc(best[0].name)}</b>: ACOS ${pct(best[1].acos, 2)}, ROAS ${best[1].roas.toFixed(1).replace('.', ',')}x, ${int(best[1].sales)} ventas y utilidad neta ${money(netProfit(best[0]))}.` : 'Ninguna campaña tiene aún 5 ventas. Simula más días.'}</p>${(() => { const mp = camps.slice().sort((a, b) => netProfit(b.c) - netProfit(a.c))[0]; return mp && best && mp.c !== best[0] ? `<p class="t-sm c-var mt8">Ojo: la campaña con mayor utilidad neta en pesos es <b>${esc(mp.c.name)}</b> (${money(netProfit(mp.c))}). Un ACOS bajo mide eficiencia; la utilidad neta mide cuánto dinero te queda. Analiza ambos antes de reasignar presupuesto.</p>` : ''; })()}</div>` : ''}</section>` : ''}
  <a class="btn pri blk" href="#/reporte">${ic('file', 's18')} Elaborar reporte de rendimiento</a></div>`;
};
ACT.checkAcos = () => { S.acos.checked = true; save(); rerender(); };
ACT.pickBest = el => { S.acos.best = el.dataset.id; save(); rerender(); };

/* ============ Reporte ============ */
function reportData(scope, range) {
  const to = S.sim.day - 1; const from = range === 'all' ? 0 : Math.max(0, S.sim.day - range); const camps = (scope === 'all' ? S.campaigns : S.campaigns.filter(c => c.id === scope)).filter(c => c.status !== 'draft');
  const rows = camps.map(c => { const m = campMetrics(c, from, to); return { name: c.name, roasT: c.roasTarget, budget: c.budgetDaily, imp: m.imp, clicks: m.clicks, cost: m.cost, sales: m.sales, revenue: m.revenue, acos: m.acos, roas: m.roas, net: netProfit(c, from, to), ads: c.ads.map(a => { const p = prodById(a.productId), x = adMetrics(a, from, to); return p ? { title: p.title, cost: x.cost, sales: x.sales, revenue: x.revenue, acos: x.acos, be: margin(p) } : null; }).filter(Boolean) }; });
  const t = allMetrics(from, to, camps); const org = organicSum(from, to);
  const b = rows.filter(r => r.sales >= 5 && isFinite(r.acos)).sort((x, y) => x.acos - y.acos)[0];
  return { from, to, rows, total: t, organic: org, best: b ? b.name : '', days: to - from + 1 };
}
function reportHTML(r) {
  const d = r.data; const nf = x => isFinite(x) ? pct(x, 2) : '—';
  return `<div class="rpt col gap12"><div><h2 class="t-h2">${esc(r.title)}</h2><p class="c-sec t-sm">${esc(S.seller.name)} · ${new Date(r.date).toLocaleDateString('es-CO')} · ${d.days > 0 ? `Días ${d.from + 1} a ${d.to + 1} (${d.days} días simulados)` : 'Sin días simulados'}</p></div>
  <div class="grid2">${statBox('Inversión', money(d.total.cost))}${statBox('Ingresos por ads', money(d.total.revenue), int(d.total.sales) + ' ventas')}${statBox('ACOS global', nf(d.total.acos))}${statBox('ROAS global', isFinite(d.total.roas) ? d.total.roas.toFixed(2).replace('.', ',') + 'x' : '—')}</div>
  <p class="t-sm">Participación de la publicidad en las ventas: <b>${pct(d.total.revenue + d.organic.revenue ? d.total.revenue / (d.total.revenue + d.organic.revenue) * 100 : 0)}</b> (orgánico: ${money(d.organic.revenue)}).</p>
  <div class="tbl-wrap"><table class="tbl"><thead><tr><th>Campaña</th><th class="num">Inversión</th><th class="num">Ventas</th><th class="num">Ingresos</th><th class="num">ACOS</th><th class="num">ROAS</th><th class="num">Utilidad neta</th></tr></thead><tbody>${d.rows.map(x => `<tr class="${x.name === d.best ? 'best' : ''}"><td class="b">${esc(x.name)}</td><td class="num">${money(x.cost)}</td><td class="num">${int(x.sales)}</td><td class="num">${money(x.revenue)}</td><td class="num">${nf(x.acos)}</td><td class="num">${isFinite(x.roas) ? x.roas.toFixed(2).replace('.', ',') + 'x' : '—'}</td><td class="num">${money(x.net)}</td></tr>`).join('')}</tbody></table></div>
  ${d.best ? `<p><b>Campaña de mejor rendimiento (menor ACOS):</b> ${esc(d.best)}</p>` : ''}
  <div class="tbl-wrap"><table class="tbl"><thead><tr><th>Anuncio</th><th class="num">Inversión</th><th class="num">Ventas</th><th class="num">ACOS</th><th class="num">Margen</th></tr></thead><tbody>${d.rows.flatMap(x => x.ads).map(a => `<tr><td>${esc(a.title.slice(0, 40))}</td><td class="num">${money(a.cost)}</td><td class="num">${int(a.sales)}</td><td class="num ${isFinite(a.acos) && a.acos > a.be ? 'bad-txt' : ''}">${nf(a.acos)}</td><td class="num">${pct(a.be)}</td></tr>`).join('')}</tbody></table></div>
  <div><h3 class="t-h3">Hallazgos</h3><p style="white-space:pre-wrap">${esc(r.findings) || '—'}</p></div><div><h3 class="t-h3">Decisión</h3><p>${esc(r.decision)}</p></div><div><h3 class="t-h3">Recomendaciones</h3><p style="white-space:pre-wrap">${esc(r.recs) || '—'}</p></div></div>`;
}
const DECISIONS = ['Escalar: aumentar presupuesto en las campañas rentables', 'Optimizar: ajustar pujas, palabras clave y publicaciones', 'Pausar: detener anuncios con ACOS superior al margen', 'Mantener: seguir monitoreando una semana más'];
VIEWS.reporte = r => {
  if (r.a) { const rp = S.reports.find(x => x.id === r.a); if (!rp) return `<div class="page">${emptyState('Reporte no encontrado', '', '<a class="btn pri" href="#/reporte">Volver</a>')}</div>`; return `<div class="page"><div class="row between noprint"><div class="row gap8"><a class="icon-btn" href="#/reporte" aria-label="Volver">${ic('arl', 's24')}</a><h1 class="t-h2">Reporte</h1></div><div class="row gap8"><button class="btn sec sm" data-act="printRpt">${ic('print', 's14')} Imprimir / PDF</button><button class="btn sec sm" data-act="dlRpt" data-id="${rp.id}">${ic('download', 's14')} HTML</button></div></div><section class="card">${reportHTML(rp)}</section></div>`; }
  if (!RPT) RPT = { title: 'Reporte de rendimiento de campañas', scope: 'all', range: 'all', findings: '', decision: DECISIONS[1], recs: '' };
  const prev = { ...RPT, date: Date.now(), data: reportData(RPT.scope, RPT.range) };
  return `<div class="page">${pageHead('Reporte de rendimiento')}${banner(7, 'Análisis de resultados', 'Elabora un reporte con los resultados de tu campaña pagada: hallazgos, decisión y recomendaciones.')}
  ${S.sim.day === 0 ? '<div class="card hl"><p class="c-var">Aún no hay días simulados. Lanza una campaña y avanza el tiempo para tener datos.</p></div>' : ''}
  <section class="card col gap12"><div class="field"><label for="rt">Título</label><input id="rt" class="inp" data-root="rp" data-set="title" value="${esc(RPT.title)}"></div>
  <div class="grid2"><div class="field"><label for="rs">Campañas</label><select id="rs" class="sel" data-root="rp" data-set="scope" data-re="1"><option value="all">Todas las campañas</option>${S.campaigns.filter(c => c.status !== 'draft').map(c => `<option value="${c.id}" ${RPT.scope === c.id ? 'selected' : ''}>${esc(c.name)}</option>`).join('')}</select></div>
  <div class="field"><label for="rr">Periodo</label><select id="rr" class="sel" data-root="rp" data-set="range" data-re="1"><option value="all" ${RPT.range === 'all' ? 'selected' : ''}>Todo el periodo</option><option value="7" ${RPT.range == 7 ? 'selected' : ''}>Últimos 7 días</option><option value="30" ${RPT.range == 30 ? 'selected' : ''}>Últimos 30 días</option></select></div></div></section>
  <section class="card">${reportHTML(prev)}</section>
  <section class="card col gap12"><div class="field"><label for="rf">Hallazgos (qué muestran los datos)</label><textarea id="rf" class="txt" data-root="rp" data-set="findings" placeholder="Ej. La campaña X tiene el menor ACOS (…%) y supera su ROAS objetivo. El anuncio Y pierde dinero porque…">${esc(RPT.findings)}</textarea></div>
  <div class="field"><label for="rd">Decisión</label><select id="rd" class="sel" data-root="rp" data-set="decision">${DECISIONS.map(d => `<option ${RPT.decision === d ? 'selected' : ''}>${d}</option>`).join('')}</select></div>
  <div class="field"><label for="rrc">Recomendaciones</label><textarea id="rrc" class="txt" data-root="rp" data-set="recs" placeholder="Acciones concretas, responsables y fecha de revisión…">${esc(RPT.recs)}</textarea></div>
  <button class="btn pri" data-act="saveRpt" ${S.sim.day === 0 ? 'disabled' : ''}>${ic('check', 's18')} Guardar reporte</button></section>
  ${S.reports.length ? `<section class="col gap8"><h3 class="t-h3">Reportes guardados</h3>${S.reports.map(x => `<div class="card row gap8"><div class="grow"><div class="b">${esc(x.title)}</div><div class="t-sm c-sec">${new Date(x.date).toLocaleString('es-CO')}</div></div><a class="btn sec sm" href="#/reporte/${x.id}">Ver</a><button class="icon-btn" style="width:36px;height:36px" data-act="delRpt" data-id="${x.id}" aria-label="Eliminar reporte">${ic('trash', 's16')}</button></div>`).join('')}</section>` : ''}</div>`;
};
document.addEventListener('change', e => { if (e.target.dataset && e.target.dataset.re && e.target.dataset.root === 'rp') rerender(); });
ACT.saveRpt = () => { const o = { ...RPT, id: uid('RPT'), date: Date.now(), range: RPT.range }; o.data = reportData(RPT.scope, RPT.range); S.reports.unshift(o); save(); toast('Reporte guardado'); go('#/reporte/' + o.id); };
ACT.delRpt = el => confirmBox('Eliminar reporte', 'Esta acción no se puede deshacer.', 'Eliminar', () => { S.reports = S.reports.filter(x => x.id !== el.dataset.id); save(); rerender(); });
ACT.printRpt = () => window.print();
ACT.dlRpt = el => { const rp = S.reports.find(x => x.id === el.dataset.id); const css = '<style>body{font-family:system-ui,sans-serif;max-width:900px;margin:24px auto;padding:0 16px;color:#0b1c30}table{border-collapse:collapse;width:100%;font-size:13px}th,td{border-bottom:1px solid #ddd;padding:6px 8px;text-align:left}.num{text-align:right}.stat{display:inline-block;margin:4px 12px 4px 0}.k{font-size:11px;color:#565e74;display:block}.v{font-weight:700;font-size:18px}.grid2{display:flex;gap:16px;flex-wrap:wrap}.best td{background:#e6f9dc}.bad-txt{color:#ba1a1a}</style>'; download('reporte-mercadosena-ads.html', `<!DOCTYPE html><html lang="es"><meta charset="utf-8"><title>${esc(rp.title)}</title>${css}<body>${reportHTML(rp)}</body></html>`, 'text/html'); };

/* ============ Ajustes de ROAS ============ */
const ROASUI = { id: null, sel: null, custom: '' };
VIEWS.roas = r => {
  if (!r.a) return `<div class="page">${pageHead('Ajustes de ROAS')}${S.campaigns.length ? `<p class="c-var">Elige la campaña cuyo ROAS objetivo quieres modificar.</p>${S.campaigns.map(c => `<a class="card row gap12" href="#/roas/${c.id}" style="color:inherit"><div class="grow"><div class="b">${esc(c.name)}</div><div class="t-sm c-sec">ROAS objetivo actual: ${c.roasTarget}x</div></div>${ic('right', 's18')}</a>`).join('')}` : emptyState('No tienes campañas', 'Crea una campaña para ajustar su ROAS objetivo.', `<button class="btn pri" data-act="newCamp">Crear campaña</button>`)}</div>`;
  const c = campById(r.a); if (!c) return `<div class="page">${emptyState('Campaña no encontrada', '', '<a class="btn pri" href="#/roas">Volver</a>')}</div>`;
  if (ROASUI.id !== c.id) { ROASUI.id = c.id; if ([2, 3, 10].includes(c.roasTarget)) { ROASUI.sel = String(c.roasTarget); ROASUI.custom = ''; } else { ROASUI.sel = 'custom'; ROASUI.custom = String(c.roasTarget); } }
  const val = ROASUI.sel === 'custom' ? num(ROASUI.custom) : +ROASUI.sel; const v = val >= 1 ? val : c.roasTarget;
  const pos = 10 + (clamp(v, 2, 10) - 2) / 8 * 80;
  const opt = (k, big, tag, tagCls, desc, rec, icon) => `<div class="opt ${ROASUI.sel === k ? 'on' : ''}" data-act="roasPick" data-k="${k}" role="radio" aria-checked="${ROASUI.sel === k}" tabindex="0" style="flex-direction:column;gap:8px">${rec ? '<span class="ribbon">★ RECOMENDADO</span>' : ''}<div class="row between" style="width:100%"><div class="row gap12"><div class="radio"><i></i></div><span class="t-h3 ${rec ? 'xb' : ''}">${big}</span><span class="c-prc">${ic(icon, 's18')}</span></div><span class="badge ${tagCls}">${tag}</span></div><p class="c-var" style="padding-left:32px">${desc}</p></div>`;
  return `<div class="page">
  <section class="card"><div class="row between"><div class="row gap8 c-prc">${ic('sliders', 's18')}<span class="t-xs up">Estrategia de puja</span></div><a class="icon-btn" style="width:32px;height:32px;background:var(--surface-c)" href="#/campanas" aria-label="Cerrar">${ic('x', 's16')}</a></div><h1 class="t-h2 mt8">Modifica tu ROAS objetivo</h1><p class="c-var t-sm mt4">Ajusta el equilibrio entre rentabilidad y volumen de ventas para tus anuncios SENA.</p><div class="row gap8 mt12" style="background:var(--surface-low);padding:4px 10px;border-radius:99px;align-self:flex-start;display:inline-flex"><span class="dotg pu"></span><span class="t-xs">Campaña: <b>${esc(c.name)}</b> · ${campStatus(c).t}</span></div></section>
  <section class="card col gap12"><div class="row between"><span class="t-lblm b">Espectro de rendimiento</span><span class="row gap4" style="background:var(--surface-low);padding:2px 8px;border-radius:8px"><span class="t-xs c-var">Actual:</span><span class="t-lbl c-prc b" id="roasbadge">${v}x</span></span></div>
  <div class="row between"><span class="t-lblm b">2x</span><span class="row c-prc t-xs">▼ Equilibrio óptimo ▼</span><span class="t-lblm b">10x</span></div>
  <div class="gauge"><div style="width:28%;background:rgba(57,169,0,.8);border-radius:99px 0 0 99px"></div><div style="width:32%;background:var(--primary-container)"></div><div style="width:40%;background:var(--amber);border-radius:0 99px 99px 0"></div><span class="pin" id="gpin" style="left:calc(${pos}% - 5px)"></span></div>
  <div class="row between t-sm c-var"><span style="max-width:45%">Más ventas con menor rentabilidad</span><span style="max-width:45%;text-align:right">Menos ventas con mayor rentabilidad</span></div></section>
  <div class="col gap12" role="radiogroup" aria-label="Opciones de ROAS">
  ${opt('2', '2x', 'Volumen', 'mut', 'Más ventas con menor rentabilidad', false, 'checkc')}${opt('3', '3x', 'Ideal SENA', 'ok', 'Equilibrado · Maximiza la exposición manteniendo margen saludable', true, 'checkc')}${opt('10', '10x', 'Alto margen', 'warn', 'Menos ventas con mayor rentabilidad', false, 'warn')}
  <div class="opt ${ROASUI.sel === 'custom' ? 'on' : ''}" data-act="roasPick" data-k="custom" role="radio" aria-checked="${ROASUI.sel === 'custom'}" tabindex="0" style="flex-direction:column;gap:8px"><div class="row between" style="width:100%"><div class="row gap12"><div class="radio"><i></i></div><span class="t-h3">Definir otro</span></div><span class="badge mut">Personalizado</span></div><div style="padding-left:32px;width:100%"><div class="row gap8" style="background:var(--surface-low);padding:6px 12px;border-radius:8px"><input id="roascustom" type="number" step="0.1" min="1" max="25" class="inp" style="background:transparent;box-shadow:none;min-height:32px;padding:0" placeholder="Ingresar (ej. 4.5)" value="${esc(ROASUI.custom)}"><span class="b c-var">x</span></div><span class="t-xs c-var mt4" style="display:block">Rango recomendado: 2.0x a 12.0x</span></div></div></div>
  <section class="card flat row gap12"><div class="num" style="background:rgba(57,169,0,.2);color:var(--primary-container)">${ic('chart', 's18')}</div><div class="col grow"><span class="t-lbl b">Impacto estimado del cambio</span><span class="t-sm c-var" id="roasproj">${roasProj(c, v)}</span></div></section>
  <div class="col gap8"><button class="btn pri blk" style="min-height:48px" data-act="saveRoas" data-id="${c.id}">${ic('send', 's18')} Guardar ROAS objetivo</button><a class="btn gho blk" href="#/campanas">Cancelar</a></div></div>`;
};
function roasProj(c, v) {
  if (!(v >= 1) || !c.ads.length) return 'Agrega anuncios a la campaña para estimar el impacto.';
  const a = campEstimate(c), b = campEstimate(c, { roasTarget: v }); const d = a.imp ? (b.imp - a.imp) / a.imp * 100 : 0; const ds = a.sales ? (b.sales - a.sales) / a.sales * 100 : 0;
  return `${d >= 0 ? '+' : ''}${d.toFixed(0)}% impresiones · ${ds >= 0 ? '+' : ''}${ds.toFixed(0)}% ventas diarias · ACOS estimado ${pct(b.acos)} (hoy ${pct(a.acos)}). ${v < c.roasTarget ? 'Más volumen, menos margen.' : v > c.roasTarget ? 'Menos volumen, más margen.' : 'Sin cambios.'}`;
}
VIEWS.roas_after = r => { const i = $('#roascustom'); if (i) i.addEventListener('input', () => { ROASUI.sel = 'custom'; ROASUI.custom = i.value; const c = campById(r.a); const v = num(i.value); $('#roasbadge').textContent = (v || '—') + 'x'; $('#roasproj').textContent = roasProj(c, v); $('#gpin').style.left = `calc(${10 + (clamp(v, 2, 10) - 2) / 8 * 80}% - 5px)`; $$('.opt[data-act="roasPick"]').forEach(o => { const on = o.dataset.k === 'custom'; o.classList.toggle('on', on); o.setAttribute('aria-checked', on); }); }); };
ACT.roasPick = (el, e) => { if (e.target.id === 'roascustom') { ROASUI.sel = 'custom'; return; } ROASUI.sel = el.dataset.k; if (el.dataset.k === 'custom') { rerender(); setTimeout(() => { const i = $('#roascustom'); if (i) i.focus(); }, 0); } else rerender(); };
ACT.saveRoas = el => { const c = campById(el.dataset.id); const v = ROASUI.sel === 'custom' ? num(ROASUI.custom) : +ROASUI.sel; if (!(v >= 1 && v <= 25)) return toast('Ingresa un ROAS entre 1 y 25', 'warn'); c.roasTarget = v; save(); toast(`ROAS objetivo guardado: ${v}x`); go('#/campanas'); };

/* ============ Datos y descarga ============ */
function download(name, text, type) { const b = new Blob([text], { type: type + ';charset=utf-8' }); const a = document.createElement('a'); a.href = URL.createObjectURL(b); a.download = name; document.body.appendChild(a); a.click(); setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 800); }
VIEWS.datos = () => `<div class="page">${pageHead('Datos y descarga')}
  <section class="card col gap12"><div class="row gap12"><div class="num">${ic('download', 's18')}</div><div><h3 class="t-h3">Descargar el simulador (HTML portable)</h3><p class="c-var">Un solo archivo que funciona sin internet en celular, tableta y computador. Compártelo por correo, WhatsApp o memoria USB. El archivo va limpio: no incluye tu trabajo. Cada estudiante crea su propia cuenta y empieza desde cero.</p></div></div><button class="btn pri" data-act="dlApp">${ic('download', 's18')} Descargar mercadosena-ads.html</button></section>
  <section class="card col gap12"><h3 class="t-h3">Tu proyecto</h3><p class="c-var">Guarda tu trabajo (productos, campañas, resultados y reportes) en un archivo para entregarlo al instructor o continuar en otro dispositivo.</p><div class="row gap8 wrap"><button class="btn sec" data-act="expData">${ic('download', 's16')} Exportar proyecto (.json)</button><label class="btn sec" tabindex="0">${ic('upload', 's16')} Importar proyecto<input type="file" id="impfile" accept="application/json,.json" hidden></label></div></section>
  <section class="card col gap12"><h3 class="t-h3">Práctica</h3><div class="row gap8 wrap"><button class="btn sec" data-act="practice">${ic('zap', 's16')} Cargar caso práctico</button><button class="btn dng" data-act="reset">${ic('trash', 's16')} Reiniciar simulador</button></div><p class="hint">El caso práctico reemplaza tu trabajo actual con 6 productos, 3 campañas y 30 días de resultados.</p></section>
  <section class="card flat col gap8"><h3 class="t-h3">Cómo funciona la simulación</h3><p class="t-sm c-var">Cada día simulado, el motor calcula impresiones según el volumen de búsqueda de cada palabra clave, tu puja frente al mercado, la audiencia elegida y la calidad de la publicación. De ahí salen clics (CTR), costo (CPC), ventas (conversión) y ACOS. Si el costo supera el presupuesto diario, se recorta. Los primeros ${LEARN_DAYS} días la campaña está en aprendizaje y rinde menos. Con ROAS objetivo, la puja se limita para no pagar más de lo rentable.</p></section></div>`;
VIEWS.datos_after = () => { const f = $('#impfile'); if (f) f.addEventListener('change', async () => { const file = f.files[0]; if (!file) return; try { const o = JSON.parse(await file.text()); if (!o || o.v !== 1 || !Array.isArray(o.products)) throw 0; confirmBox('Importar proyecto', 'Reemplazará todo tu trabajo actual.', 'Importar', () => { S = Object.assign(blank(), o); save(); toast('Proyecto importado'); go('#/inicio'); }); } catch (e) { toast('El archivo no es un proyecto válido', 'warn'); } }); };
ACT.dlApp = () => download('mercadosena-ads.html', ORIGINAL_HTML, 'text/html');
ACT.expData = () => download('proyecto-mercadosena-ads.json', JSON.stringify(S), 'application/json');
ACT.reset = () => confirmBox('Reiniciar simulador', 'Se borrarán productos, campañas, resultados y reportes.', 'Reiniciar', () => { S = blank(); PD = null; RPT = null; UI.pending = {}; save(); toast('Simulador reiniciado'); go('#/inicio'); });
ACT.practice = () => confirmBox('Cargar caso práctico', 'Reemplazará tu trabajo actual por datos de ejemplo.', 'Cargar', () => { loadPractice(); toast('Caso práctico cargado: 30 días simulados'); go('#/metricas'); });

/* ============ Caso práctico ============ */
function loadPractice() {
  S = blank(); PD = null; RPT = null; UI.pending = {};
  const mk = (title, cat, price, cost, stock, desc, nimg) => { const p = { id: String(Math.floor(100000000 + Math.random() * 900000000)), title, desc, cat, price, cost, stock, images: [] }; for (let i = 0; i < nimg; i++) p.images.push(sampleImage(p, i)); S.products.push(p); return p; };
  const cafe = mk('Café Especial Origen Huila Tostión Media 500 g', 'alimentos', 38000, 27000, 900, 'Café de altura cultivado por familias del Huila, tostión media con notas a panela, cacao y frutos rojos. Empaque con válvula que conserva la frescura. Ideal para prensa francesa, V60 y cafetera de goteo. Trazabilidad por lote.', 3);
  const miel = mk('Miel de Abejas Pura 1 kg', 'alimentos', 42000, 31000, 600, 'Miel natural.', 1);
  const hidro = mk('Hidrolavadora Portátil Multi-Uso SENA Pro 1800 W', 'herramientas', 246500, 190000, 300, 'Hidrolavadora eléctrica de 1800 W y 120 bar para limpieza de fachadas, vehículos, patios y maquinaria agrícola. Incluye manguera de 5 metros, lanza ajustable y garantía de un año con soporte técnico.', 3);
  const panela = mk('Panela Orgánica Artesanal en Bloque 1 kg', 'alimentos', 12000, 9000, 1200, 'Panela orgánica elaborada en trapiche familiar sin químicos ni aditivos. Bloque de un kilo, ideal para aguapanela, repostería y bebidas calientes. Empaque sellado con hoja de bijao.', 2);
  const mochila = mk('Mochila Wayuu Tejida a Mano Mediana Colores Vivos', 'artesanias', 95000, 62000, 120, 'Mochila tejida a mano por artesanas wayuu de La Guajira, hilo de algodón resistente, correa ajustable y diseño único. Mide 30 por 30 centímetros. Cada pieza es irrepetible.', 3);
  const aceite = mk('Aceite Esencial de Lavanda Orgánico 30 ml', 'belleza', 28000, 15000, 400, 'Aceite esencial de lavanda 100% puro, destilado al vapor, en frasco de vidrio ámbar con gotero. Para aromaterapia, difusores, masajes diluidos y descanso nocturno. Libre de parabenos y fragancias.', 2);
  const aud = f => { const a = blankAudience(); f(a); a.touched = true; return a; };
  const camp = (name, roas, budget, bid, audience, ads, groups, neg) => { const c = newCamp(); c.name = name; c.roasTarget = roas; c.budgetDaily = budget; c.bid = bid; c.audience = audience; c.groups = groups.map(g => ({ id: uid('BLQ'), name: g })); ads.forEach(([p, gi, kws]) => { addAdTo(c, p.id, c.groups[gi].id); c.ads[c.ads.length - 1].keywords = kws.map(([t, m, b]) => ({ term: t, match: m, bid: b || bid })); }); c.negatives = neg || []; c.status = 'active'; c.startDay = 0; c.durationDays = 90; delete c.step; S.campaigns.push(c); return c; };
  camp('Emprendedores SENA Agro', 3, 20000, 200, aud(a => { }), [[cafe, 0, [['café especial', 'frase'], ['café huila 500 g', 'exacta', 220]]], [hidro, 1, [['hidrolavadora portátil', 'frase', 260], ['hidrolavadora 1800 w', 'exacta', 280]]], [panela, 1, [['panela orgánica', 'frase', 150]]]], ['Línea Café', 'Herramientas y despensa'], ['usado', 'repuesto']);
  camp('Línea Café y Miel', 5, 12000, 160, aud(a => { a.behavior.buyers = ['plataforma', 'tienda']; a.behavior.interests = ['alimentos', 'gourmet']; }), [[cafe, 0, [['café', 'amplia', 150], ['café de origen', 'frase']]], [miel, 0, [['miel', 'amplia', 150]]]], ['Bloque 1']);
  camp('Bienestar y Artesanías', 2, 10000, 140, aud(a => { a.geo.scope = 'ciudades'; a.geo.cities = ['Bogotá', 'Medellín', 'Cali']; a.demo.ageMin = 25; a.demo.ageMax = 54; a.demo.genders = ['mujer']; a.behavior.interests = ['regalos', 'belleza']; }), [[mochila, 0, [['mochila wayuu', 'exacta', 170], ['mochila artesanal', 'frase']]], [aceite, 1, [['aceite esencial lavanda', 'frase', 150]]]], ['Artesanías', 'Bienestar'], []);
  advance(30);
}
